-- gen622: 9 zone cambiate, 19 tessere
-- c230922976fc1191d6f38b868edb753f (1047212) → 5319ff40121d588ae12991f6178128e2 (1052950)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '5319ff40121d588ae12991f6178128e2' as combacia
from kv_store where key like 'tmp:gen622:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen622:p%')
where key='app:jsx:src'
  and md5(value) = 'c230922976fc1191d6f38b868edb753f'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen622:p%') = '5319ff40121d588ae12991f6178128e2';

update kv_store set value = '{"len":1052950,"ver":"gen-6.22"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '5319ff40121d588ae12991f6178128e2';

delete from kv_store where key like 'tmp:gen622:p%';
